*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.fn_SetPar, scwin.strCdSch;
scwin.vScrenID = "ULDINS90200.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_rdochange = function() {
    if ($c.stf.getObjectValue(rdo_searchType) == "1") {
        $c.stf.showObj(panel_1, true);
        $c.stf.showObj(panel_2, false);
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(label_9, false);
    } else {
        $c.stf.showObj(panel_1, false);
        $c.stf.showObj(panel_2, true);
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(label_9, true);
    }
};
scwin.fn_list_sync = function() {
    /*var url = "/listingCommon.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listZipCd";
         url += "&inputMessageId=ZIPCD_OUT&outputMessageId=ZIPCD_OUT" ;			 
    	 url += "&SEARCHTYPE=" +getObjectValue(rdo_searchType) +"&SEARCHDTL_1=" +getObjectValue(txb_Search_1) + "&SEARCHDTL_2=" + getObjectValue(txb_Search_2) ;
    dts_List.DataID = encodeURI(url); 
    dts_List.reset();*/

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS90200_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listZipCdInquiry" + "&{P}SEARCHTYPE=" + $c.stf.getObjectValue(rdo_searchType) + "&{P}SEARCHDTL_1=" + $c.stf.getObjectValue(txb_Search_1) + "&{P}SEARCHDTL_2=" + $c.stf.getObjectValue(txb_Search_2);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.checkValues = function() {
    if ($c.stf.getObjectValue(txb_Search_1).indexOf('%') != -1 || $c.stf.getObjectValue(txb_Search_2).indexOf('%') != -1) {
        $c.win.alert("'%' 문자는 입력할 수 없습니다.");
        return false;
    }

    // 도로명 검색
    if ($c.stf.getObjectValue(rdo_searchType) == "1") {
        var searchWord = $c.stf.getObjectValue(txb_Search_1);
        $c.stf.setObjectValue(txb_Search_1, searchWord); // 공백제거한 값을 다시 입력
        if (searchWord.length < 2) {
            $c.win.alert("도로명은 최소 2글자 이상 입력하세요.");
            txb_Search_1.focus();
            return false;
        } else {
            return true;
        }
        // 건물명 검색

    } else {
        var searchWord = $c.stf.getObjectValue(txb_Search_2);
        $c.stf.setObjectValue(txb_Search_2, searchWord); // 공백제거한 값을 다시 입력
        if (searchWord.length < 2) {
            $c.win.alert("건물명은 최소 2글자 이상 입력하세요.");
            txb_Search_2.focus();
            return false;
        } else {
            return true;
        }
    }
};
scwin.txb_Search_1_onkeydown = function() {
    if (event.keyCode == 13) {
        if (!scwin.checkValues()) {
            return;
        }
        scwin.fn_list_sync();
    }
};
scwin.txb_Search_2_onkeydown = function() {
    if (event.keyCode == 13) {
        if (!scwin.checkValues()) {
            return;
        }
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총 " + rowcount + " 건");
    if (scwin.strCdSch != "") {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            if (scwin.strCdSch == dts_List.getCellData(i, 1)) {
                dts_List.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strCdSch = "";
    }
    $c.cm.ShowWin(grd_List);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.rdo_searchType_OnSelChange = function() {
    scwin.fn_rdochange();
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    var arrPar = new Array();

    //if (fn_SetPar != undefined) {
    var ZIPCD = dts_List.getCellData(row, "ZIPCD");
    var ADDR = dts_List.getCellData(row, "ADDR");
    var ENG_ADDR = dts_List.getCellData(row, "ENG_ADDR");

    //arrPar[0] = dts_List.NameValue( dts_List.RowPosition, 'ZIPCD');
    //arrPar[1] = dts_List.NameValue( dts_List.RowPosition, 'ADDR');
    //arrPar[2] = dts_List.NameValue( dts_List.RowPosition, 'ZIPCD_SEQ');

    $c.frame.path("../").ins_popupRtn_cdnm2(ZIPCD, ADDR, ENG_ADDR);
    //}

    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    if (!scwin.checkValues()) {
        return;
    }
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_rdochange();
    window.document.body.scroll = "no";
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    //fn_list_sync();
    txb_Search_1.focus();
};
